import json
import pandas as pd

OUT = "/workspace/merged_records.csv"
records = {}


def norm(v):
    if v is None:
        return ""
    if isinstance(v, float) and pd.isna(v):
        return ""
    return str(v).strip()


def add(email, phone, status):
    e = norm(email).lower()
    if not e:
        return
    r = records.setdefault(e, {"email": e, "phone": "", "status": ""})
    if not r["phone"] and norm(phone):
        r["phone"] = norm(phone)
    if not r["status"] and norm(status):
        r["status"] = norm(status)


# users.csv
users = pd.read_csv("/workspace/users.csv", dtype=str, keep_default_na=False)
for row in users.to_dict("records"):
    add(row.get("email"), row.get("phone"), row.get("status"))

# records.jsonl
with open("/workspace/records.jsonl", encoding="utf-8") as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        rec = json.loads(line)
        other = rec.get("other_info") or {}
        add(rec.get("email"), rec.get("phone") or other.get("phone"), rec.get("status"))

# profiles.json
with open("/workspace/profiles.json", encoding="utf-8") as f:
    prof = json.load(f)
if isinstance(prof, dict):
    items = list(prof.items())
else:
    items = [(None, p) for p in prof]
for key, rec in items:
    if not isinstance(rec, dict):
        continue
    other = rec.get("other_info") or {}
    add(rec.get("email") or key, rec.get("phone") or other.get("phone"), rec.get("status"))

out = pd.DataFrame(list(records.values()), columns=["email", "phone", "status"])
out.to_csv(OUT, index=False)
print(len(out), "unique users written to", OUT)
EOF
